import{_ as r,c as a,o,ae as t,j as n}from"./chunks/framework.tuuL-SzM.js";const s="/spelunky-remake/spelunky-demo.mp4",l="/spelunky-remake/ScreenShot1.png",g=JSON.parse('{"title":"Spelunky remake","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"projects/spelunky-remake.md","filePath":"projects/spelunky-remake.md","lastUpdated":1757879873000}'),p={name:"projects/spelunky-remake.md"},i=s+"#t=10";function h(u,e,c,m,k,d){return o(),a("div",null,e[0]||(e[0]=[t('<h1 id="spelunky-remake" tabindex="-1">Spelunky remake <a class="header-anchor" href="#spelunky-remake" aria-label="Permalink to &quot;Spelunky remake&quot;">​</a></h1><p>I recreated <a href="https://store.steampowered.com/app/239350/Spelunky/" target="_blank" rel="noreferrer">spelunky</a> using using c++.</p><h1 id="play-here" tabindex="-1"><a href="/spelunky-remake/spelunky.html" target="_self">PLAY HERE</a> <a class="header-anchor" href="#play-here" aria-label="Permalink to &quot;[PLAY HERE](/spelunky-remake/spelunky.html){target=&quot;_self&quot;}&quot;">​</a></h1><p>This was my first year DAE project.</p><p>I used the book Spelunky by Derek Yu (The creator of spelunky) to get inspiration how to implement the random world generator.</p>',5),n("video",{controls:"",src:i},null,-1),t('<p>After I was done with it for a school project I decided to make it into a web game with emscripten. There where some problems I had when porting the game.</p><h3 id="porting-opengl" tabindex="-1">Porting opengl <a class="header-anchor" href="#porting-opengl" aria-label="Permalink to &quot;Porting opengl&quot;">​</a></h3><p>The engine was written in opengl 1.0 which doesn&#39;t work with emscripten. I upgraded the engine to use opengl 2.0 ES so it can draw in webgl.</p><p>In opengl 1.0 there are no shaders. So I added them for opengl 2.0 ES to work. You can also push matrix in opengl 1.0. This feature doesn&#39;t exists in opengl 2.0 ES. I recreated that feature.</p><ul><li>Github: <a href="https://github.com/GeleArthur/Spelunky-Remake" target="_blank" rel="noreferrer">https://github.com/GeleArthur/Spelunky-Remake</a></li></ul><h1 id="screenshot" tabindex="-1">Screenshot <a class="header-anchor" href="#screenshot" aria-label="Permalink to &quot;Screenshot&quot;">​</a></h1><p><img src="'+l+'" alt="Spelunky remake"></p>',7)]))}const y=r(p,[["render",h]]);export{g as __pageData,y as default};
